(function () {
'use strict';
var doc = document;
var dock = doc.querySelector('[data-dock]');
var results = doc.querySelector('[data-dock-results]');
if (!dock || !results) {
return;
}
var MAGNIFICATION = 1.55;
var PITCHES = 3; // Radio de influencia: unas 3 veces el paso entre íconos.
var BAR_PADDING = 8;
var POINTER_TAU = 45; // ms: suavizado del cursor y de la entrada/salida.
var INFLUENCE_TAU = 75;
var EASE = 'cubic-bezier(0.22, 1, 0.36, 1)';
var frame = dock.querySelector('.dock__frame');
var bar = dock.querySelector('.dock__bar');
var row = dock.querySelector('.dock__row');
var items = Array.prototype.slice.call(row.querySelectorAll('.dock__item'));
var links = items.map(function (item) { return item.querySelector('.dock__link'); });
var grid = results.querySelector('.grid-cards');
var title = results.querySelector('[data-dock-title]');
var count = results.querySelector('[data-dock-count]');
var hoverQuery = window.matchMedia('(hover: hover) and (pointer: fine) and (min-width: 700px)');
var calmQuery = window.matchMedia('(prefers-reduced-motion: reduce)');
function falloffAt(delta, distance) {
var spread = Math.abs(delta);
return spread >= distance ? 0 : (Math.cos((Math.PI * spread) / distance) + 1) * 0.5;
}
function falloffIntegral(delta, distance) {
var sign = delta < 0 ? -1 : 1;
var spread = Math.min(Math.abs(delta), distance);
return sign * ((distance / (2 * Math.PI)) * Math.sin((Math.PI * spread) / distance) + spread * 0.5);
}
function restingCenter(index, field) {
return index * (field.base + field.gap) + field.base * 0.5;
}
function gainOf(field) {
return field.influence * (MAGNIFICATION - 1);
}
function scaleAt(index, field) {
return 1 + gainOf(field) * falloffAt(restingCenter(index, field) - field.pointer, field.distance);
}
function centreShift(field) {
var first = restingCenter(0, field) - field.pointer;
var last = restingCenter(field.count - 1, field) - field.pointer;
return (falloffIntegral(first, field.distance) + falloffIntegral(last, field.distance)) * 0.5
+ field.base * (falloffAt(last, field.distance) - falloffAt(first, field.distance)) * 0.25;
}
function centreAt(index, field) {
var resting = restingCenter(index, field);
return resting + gainOf(field) * (falloffIntegral(resting - field.pointer, field.distance) - centreShift(field));
}
function rowLength(field) {
var last = field.count - 1;
var start = centreAt(0, field) - field.base * scaleAt(0, field) * 0.5;
var end = centreAt(last, field) + field.base * scaleAt(last, field) * 0.5;
return end - start;
}
function solvePointer(rendered, field) {
var probe = {
base: field.base, gap: field.gap, count: field.count, distance: field.distance,
influence: field.influence, pointer: rendered
};
for (var step = 0; step < 3; step += 1) {
probe.pointer = rendered + gainOf(probe) * centreShift(probe);
}
return probe.pointer;
}
var field = { base: 0, gap: 0, count: items.length, distance: 0, influence: 0, pointer: 0 };
var targetPointer = 0;
var targetInfluence = 0;
var tracking = false;
var raf = 0;
var lastFrame = 0;
function magnetic() {
return hoverQuery.matches && !calmQuery.matches;
}
function measure() {
field.base = links[0].offsetWidth;
field.gap = parseFloat(window.getComputedStyle(row).columnGap) || 0;
field.distance = (field.base + field.gap) * PITCHES;
}
function paint() {
var solved = {
base: field.base, gap: field.gap, count: field.count, distance: field.distance,
influence: field.influence, pointer: solvePointer(field.pointer, field)
};
items.forEach(function (item, index) {
var scale = scaleAt(index, solved);
item.style.transform = 'translateX(' + (centreAt(index, solved) - restingCenter(index, solved)).toFixed(2) + 'px)';
links[index].style.transform = 'scale(' + scale.toFixed(4) + ')';
item.style.setProperty('--dock-lift', (-(scale - 1) * field.base).toFixed(2) + 'px');
});
bar.style.width = (rowLength(solved) + BAR_PADDING * 2).toFixed(2) + 'px';
}
function clearPaint() {
items.forEach(function (item, index) {
item.style.removeProperty('transform');
item.style.removeProperty('--dock-lift');
links[index].style.removeProperty('transform');
});
bar.style.removeProperty('width');
}
function tick(now) {
var delta = Math.min(now - lastFrame, 48);
lastFrame = now;
field.pointer += (targetPointer - field.pointer) * (1 - Math.exp(-delta / POINTER_TAU));
field.influence += (targetInfluence - field.influence) * (1 - Math.exp(-delta / INFLUENCE_TAU));
var settled = Math.abs(targetPointer - field.pointer) < 0.1 && Math.abs(targetInfluence - field.influence) < 0.002;
if (settled) {
field.pointer = targetPointer;
field.influence = targetInfluence;
}
paint();
raf = settled ? 0 : window.requestAnimationFrame(tick);
}
function wake() {
if (!raf) {
lastFrame = window.performance.now();
raf = window.requestAnimationFrame(tick);
}
}
function aim(pointer) {
measure();
if (!tracking) {
field.pointer = pointer;
tracking = true;
}
targetPointer = pointer;
targetInfluence = 1;
wake();
}
function release() {
tracking = false;
targetInfluence = 0;
wake();
}
dock.addEventListener('pointermove', function (event) {
if (magnetic() && event.pointerType === 'mouse') {
aim(event.clientX - frame.getBoundingClientRect().left);
}
});
dock.addEventListener('pointerleave', function () {
if (magnetic()) {
release();
}
});
function onQueryChange() {
if (!magnetic()) {
window.cancelAnimationFrame(raf);
raf = 0;
tracking = false;
field.influence = 0;
targetInfluence = 0;
clearPaint();
}
}
[hoverQuery, calmQuery].forEach(function (query) {
query.addEventListener('change', onQueryChange);
});
function focusItem(index) {
var next = (index + links.length) % links.length;
links.forEach(function (link, i) {
link.tabIndex = i === next ? 0 : -1;
});
links[next].focus();
}
links.forEach(function (link, index) {
link.tabIndex = link.getAttribute('aria-current') ? 0 : -1;
link.addEventListener('keydown', function (event) {
var moves = { ArrowRight: index + 1, ArrowLeft: index - 1, Home: 0, End: links.length - 1 };
if (Object.prototype.hasOwnProperty.call(moves, event.key)) {
event.preventDefault();
focusItem(moves[event.key]);
}
});
link.addEventListener('focus', function () {
if (magnetic() && link.matches(':focus-visible')) {
measure();
aim(restingCenter(index, field));
}
});
link.addEventListener('blur', function () {
if (magnetic() && !dock.matches(':hover')) {
release();
}
});
});
var request = 0;
var cache = {};
var snapshot = grid.cloneNode(true);
Array.prototype.forEach.call(snapshot.children, function (card) {
card.classList.remove('reveal', 'is-in');
card.style.removeProperty('--reveal-delay');
});
var featured = { html: snapshot.innerHTML, title: title.textContent, count: count.textContent };
function bounce(link) {
var tile = link.querySelector('.dock__tile');
if (calmQuery.matches || typeof tile.animate !== 'function') {
return;
}
var size = link.offsetWidth;
tile.animate([
{ transform: 'translateY(0)', offset: 0, easing: 'cubic-bezier(0.23, 1, 0.32, 1)' },
{ transform: 'translateY(' + (-0.4 * size) + 'px)', offset: 0.3, easing: 'cubic-bezier(0.55, 0, 1, 0.45)' },
{ transform: 'translateY(0)', offset: 0.58, easing: 'cubic-bezier(0.23, 1, 0.32, 1)' },
{ transform: 'translateY(' + (-0.13 * size) + 'px)', offset: 0.8, easing: 'cubic-bezier(0.55, 0, 1, 0.45)' },
{ transform: 'translateY(0)', offset: 1 }
], { duration: 600 });
}
function markCurrent(link) {
links.forEach(function (other) {
if (other === link) {
other.setAttribute('aria-current', 'true');
other.tabIndex = 0;
} else {
other.removeAttribute('aria-current');
other.tabIndex = -1;
}
});
link.scrollIntoView({ block: 'nearest', inline: 'center', behavior: calmQuery.matches ? 'auto' : 'smooth' });
}
function fadeOut() {
if (calmQuery.matches || typeof results.animate !== 'function') {
return Promise.resolve(null);
}
var animation = results.animate([
{ opacity: 1, filter: 'blur(0)', transform: 'none' },
{ opacity: 0, filter: 'blur(4px)', transform: 'translateY(6px)' }
], { duration: 240, easing: EASE, fill: 'forwards' });
return animation.finished.then(function () { return animation; });
}
function enter(outAnimation) {
if (outAnimation) {
outAnimation.cancel();
}
if (calmQuery.matches || typeof results.animate !== 'function') {
return;
}
Array.prototype.forEach.call(grid.children, function (card, index) {
card.animate([
{ opacity: 0, filter: 'blur(6px)', transform: 'translateY(12px)' },
{ opacity: 1, filter: 'blur(0)', transform: 'none' }
], { duration: 640, delay: Math.min(index, 8) * 55, easing: EASE, fill: 'backwards' });
});
}
function fetchCategory(link) {
var key = link.getAttribute('data-dock-key');
if (cache[key]) {
return Promise.resolve(cache[key]);
}
return window.fetch(link.href, { credentials: 'same-origin' }).then(function (response) {
if (!response.ok) {
throw new Error('HTTP ' + response.status);
}
return response.text();
}).then(function (html) {
var page = new DOMParser().parseFromString(html, 'text/html');
var nextGrid = page.querySelector('.section--list .grid-cards');
var nextCount = page.querySelector('.section--list .list-count');
if (!nextGrid || !nextCount) {
throw new Error('Respuesta sin listado');
}
cache[key] = {
html: nextGrid.innerHTML,
title: link.getAttribute('data-dock-label'),
count: nextCount.textContent
};
return cache[key];
});
}
function showResults() {
var box = results.getBoundingClientRect();
if (dock.getBoundingClientRect().top < 0 || box.top > window.innerHeight * 0.72) {
dock.scrollIntoView({ block: 'start', behavior: calmQuery.matches ? 'auto' : 'smooth' });
}
}
function select(link) {
var id = ++request;
var key = link.getAttribute('data-dock-key');
var data = key === '' ? Promise.resolve(featured) : fetchCategory(link);
markCurrent(link);
bounce(link);
grid.style.minHeight = grid.offsetHeight + 'px';
Promise.all([data, fadeOut()]).then(function (done) {
if (id !== request) {
return;
}
grid.innerHTML = done[0].html;
grid.scrollLeft = 0;
title.textContent = done[0].title;
count.textContent = done[0].count;
grid.style.removeProperty('min-height');
doc.dispatchEvent(new CustomEvent('tt:cards', { detail: grid }));
enter(done[1]);
showResults();
}).catch(function () {
window.location.href = link.href;
});
}
if (typeof window.fetch !== 'function') {
return;
}
row.addEventListener('click', function (event) {
var link = event.target.closest ? event.target.closest('.dock__link') : null;
if (!link || event.defaultPrevented || event.button !== 0 || event.metaKey || event.ctrlKey || event.shiftKey || event.altKey) {
return;
}
event.preventDefault();
if (link.getAttribute('aria-current')) {
bounce(link);
return;
}
select(link);
});
})();
